using Microsoft.Extensions.Logging;

namespace Pragmatic.Logging.Benchmarks;

/// <summary>
///     The SourceGenerated category's call site, generated by Pragmatic instead of Microsoft: same template,
///     same arguments, so the CallSite category reads against SourceGenerated row by row.
/// </summary>
/// <remarks>
///     The simple name binds to Pragmatic's attribute in this project; <see cref="BenchmarkLog" /> names
///     Microsoft's in full.
/// </remarks>
internal static partial class BenchmarkCallSiteLog
{
    [LoggerMessage(Level = LogLevel.Information, Message = "Order {OrderId} processed for user {UserId}")]
    public static partial void OrderProcessed(ILogger logger, int orderId, string userId);
}
